//go:build arm64

package floats

// Add, Sub, Div, Sqrt and ClampScalar kernels (binop.go), generated by go-asmgen
// (binop_arm64_gen.go) into binop_arm64.s. NEON is the ARMv8-A baseline: no gate.
// The callers pass every slice already sliced to the common length.
func addNEON(dst, a, b []float64)
func subNEON(dst, a, b []float64)
func divNEON(dst, a, b []float64)
func sqrtNEON(dst, src []float64)
func clampScalarNEON(dst, v []float64, lo, hi float64)

func add(dst, a, b []float64) { addNEON(dst, a, b) }
func sub(dst, a, b []float64) { subNEON(dst, a, b) }
func div(dst, a, b []float64) { divNEON(dst, a, b) }
func sqrt(dst, src []float64) { sqrtNEON(dst, src) }
func clampScalar(dst, v []float64, lo, hi float64) {
	clampScalarNEON(dst, v, lo, hi)
}
